31	import { assertCanManageProjectWorkspaceRuntimeServices } from "./workspace-runtime-service-authz.js";
32	import { getTelemetryClient } from "../telemetry.js";
33	import { appendWithCap } from "../adapters/utils.js";
34	import { assertEnvironmentSelectionForCompany } from "./environment-selection.js";
35	import { environmentService } from "../services/environments.js";
36	import { secretService } from "../services/secrets.js";
37	import type { Handler, RequestCtx } from "../http/types.js";
38	import { expressHandler } from "../http/express-adapter.js";
39	
40	const WORKSPACE_CONTROL_OUTPUT_MAX_CHARS = 256 * 1024;
41	const SHARED_WORKSPACE_STOP_AND_RESTART_ACTIONS = new Set(["stop", "restart"]);
42	
43	export function projectRoutes(db: Db) {
44	  const router = Router();
45	  const svc = projectService(db);
46	  const secretsSvc = secretService(db);
47	  const workspaceOperations = workspaceOperationService(db);
48	  const strictSecretsMode = process.env.PAPERCLIP_SECRETS_STRICT_MODE === "true";
49	  const environmentsSvc = environmentService(db);
50	
51	  async function assertProjectEnvironmentSelection(companyId: string, environmentId: string | null | undefined) {
52	    if (environmentId === undefined || environmentId === null) return;
53	    await assertEnvironmentSelectionForCompany(environmentsSvc, companyId, environmentId, {
54	      allowedDrivers: ["local", "ssh", "sandbox"],
55	    });
56	  }
57	
58	  function readProjectPolicyEnvironmentId(policy: unknown): string | null | undefined {
59	    if (!policy || typeof policy !== "object" || !("environmentId" in policy)) {
60	      return undefined;
61	    }
62	    const environmentId = (policy as { environmentId?: unknown }).environmentId;
63	    return typeof environmentId === "string" || environmentId === null ? environmentId : undefined;
64	  }
65	
66	  async function resolveCompanyIdForProjectReference(ctx: RequestCtx) {
67	    const companyIdQuery = ctx.query("companyId");
68	    const requestedCompanyId =
69	      typeof companyIdQuery === "string" && companyIdQuery.trim().length > 0
70	        ? companyIdQuery.trim()
71	        : null;
72	    if (requestedCompanyId) {
73	      assertCompanyAccess(ctx, requestedCompanyId);
74	      return requestedCompanyId;
75	    }
76	    if (ctx.actor?.type === "agent" && ctx.actor.companyId) {
77	      return ctx.actor.companyId;
78	    }
79	    return null;
80	  }
81	
82	  async function normalizeProjectReference(ctx: RequestCtx, rawId: string) {
83	    if (isUuidLike(rawId)) return rawId;
84	    const companyId = await resolveCompanyIdForProjectReference(ctx);
85	    if (!companyId) return rawId;
86	    const resolved = await svc.resolveByReference(companyId, rawId);
87	    if (resolved.ambiguous) {
88	      throw conflict("Project shortname is ambiguous in this company. Use the project ID.");
89	    }
90	    return resolved.project?.id ?? rawId;
91	  }
92	
93	  router.param("id", async (req: Request, _res: ExpressResponse, next: NextFunction, rawId: string) => {
94	    try {
95	      // Build a minimal RequestCtx-compatible object for Express middleware.
96	      // req.query is an object in Express; wrap it so helpers can call ctx.query(name).
97	      const minCtx = {
98	        actor: req.actor ?? null,
99	        method: req.method,
100	        query(name: string) {
101	          const v = req.query[name];
102	          return typeof v === "string" ? v : undefined;
103	        },
104	      } as unknown as RequestCtx;
105	      req.params.id = await normalizeProjectReference(minCtx, rawId);
106	      next();
107	    } catch (err) {
108	      next(err);
109	    }
110	  });
111	
112	  // Storage is not used by project handlers; supply a sentinel to satisfy AdapterDeps.
113	  const storageSentinel = new Proxy({} as import("../storage/types.js").StorageService, {
114	    get(_target, prop) {
115	      throw new Error(`project handler unexpectedly accessed storage.${String(prop)}`);
116	    },
117	  });
118	
119	  const listProjects: Handler = async (ctx) => {
120	    const companyId = ctx.param("companyId")!;
121	    assertCompanyAccess(ctx, companyId);
122	    const result = await svc.list(companyId);
123	    return Response.json(result);
124	  };
125	
126	  const getProject: Handler = async (ctx) => {
127	    const id = ctx.param("id")!;
128	    const project = await svc.getById(id);
129	    if (!project) {
130	      return Response.json({ error: "Project not found" }, { status: 404 });
131	    }
132	    assertCompanyAccess(ctx, project.companyId);
133	    return Response.json(project);
134	  };
135	
136	  const createProject: Handler = async (ctx) => {
137	    const companyId = ctx.param("companyId")!;
138	    assertCompanyAccess(ctx, companyId);
139	    type CreateProjectPayload = Parameters<typeof svc.create>[1] & {
140	      workspace?: Parameters<typeof svc.createWorkspace>[1];
141	    };
142	
143	    const { workspace, ...projectData } = (await ctx.json()) as CreateProjectPayload;
144	    await assertProjectEnvironmentSelection(
145	      companyId,
146	      readProjectPolicyEnvironmentId(projectData.executionWorkspacePolicy),
147	    );
148	    assertNoAgentHostWorkspaceCommandMutation(
149	      ctx,
150	      [
151	        ...collectProjectExecutionWorkspaceCommandPaths(projectData.executionWorkspacePolicy),
152	        ...collectProjectWorkspaceCommandPaths(workspace, "workspace"),
153	      ],
154	    );
155	    if (projectData.env !== undefined) {
156	      projectData.env = await secretsSvc.normalizeEnvBindingsForPersistence(
157	        companyId,
158	        projectData.env,
159	        { strictMode: strictSecretsMode, fieldPath: "env" },
160	      );
161	    }
162	    const project = await svc.create(companyId, projectData);
163	    let createdWorkspaceId: string | null = null;
164	    if (workspace) {
165	      const createdWorkspace = await svc.createWorkspace(project.id, workspace);
166	      if (!createdWorkspace) {
167	        await svc.remove(project.id);
168	        return Response.json({ error: "Invalid project workspace payload" }, { status: 422 });
169	      }
170	      createdWorkspaceId = createdWorkspace.id;
171	    }
172	    const hydratedProject = workspace ? await svc.getById(project.id) : project;
173	
174	    const actor = getActorInfo(ctx);
175	    await logActivity(db, {
176	      companyId,
177	      actorType: actor.actorType,
178	      actorId: actor.actorId,
179	      agentId: actor.agentId,
180	      action: "project.created",
181	      entityType: "project",
182	      entityId: project.id,
183	      details: {
184	        name: project.name,
185	        workspaceId: createdWorkspaceId,
186	        envKeys: project.env ? Object.keys(project.env).sort() : [],
187	      },
188	    });
189	    const telemetryClient = getTelemetryClient();
190	    if (telemetryClient) {
191	      trackProjectCreated(telemetryClient);
192	    }
193	    return Response.json(hydratedProject ?? project, { status: 201 });
194	  };
195	
196	  const updateProject: Handler = async (ctx) => {
197	    const id = ctx.param("id")!;
198	    const existing = await svc.getById(id);
199	    if (!existing) {
200	      return Response.json({ error: "Project not found" }, { status: 404 });
201	    }
202	    assertCompanyAccess(ctx, existing.companyId);
203	    const body = { ...(await ctx.json<Record<string, unknown>>()) };
204	    assertNoAgentHostWorkspaceCommandMutation(
205	      ctx,
206	      collectProjectExecutionWorkspaceCommandPaths(body.executionWorkspacePolicy),
207	    );
208	    await assertProjectEnvironmentSelection(
209	      existing.companyId,
210	      readProjectPolicyEnvironmentId(body.executionWorkspacePolicy),
211	    );
212	    if (typeof body.archivedAt === "string") {
213	      body.archivedAt = new Date(body.archivedAt);
214	    }
215	    if (body.env !== undefined) {
216	      body.env = await secretsSvc.normalizeEnvBindingsForPersistence(existing.companyId, body.env, {
217	        strictMode: strictSecretsMode,
218	        fieldPath: "env",
219	      });
220	    }
221	    const project = await svc.update(id, body);
222	    if (!project) {
223	      return Response.json({ error: "Project not found" }, { status: 404 });
224	    }
225	
226	    const actor = getActorInfo(ctx);
227	    await logActivity(db, {
228	      companyId: project.companyId,
229	      actorType: actor.actorType,
230	      actorId: actor.actorId,
231	      agentId: actor.agentId,
232	      action: "project.updated",
233	      entityType: "project",
234	      entityId: project.id,
235	      details: {
236	        changedKeys: Object.keys(body).sort(),
237	        envKeys:
238	          body.env && typeof body.env === "object" && !Array.isArray(body.env)
239	            ? Object.keys(body.env as Record<string, unknown>).sort()
240	            : undefined,
241	      },
242	    });
243	
244	    return Response.json(project);
245	  };
246	
247	  const listProjectWorkspaces: Handler = async (ctx) => {
248	    const id = ctx.param("id")!;
249	    const existing = await svc.getById(id);
250	    if (!existing) {
251	      return Response.json({ error: "Project not found" }, { status: 404 });
252	    }
253	    assertCompanyAccess(ctx, existing.companyId);
254	    const workspaces = await svc.listWorkspaces(id);
255	    return Response.json(workspaces);
256	  };
257	
258	  const createProjectWorkspace: Handler = async (ctx) => {
259	    const id = ctx.param("id")!;
260	    const existing = await svc.getById(id);
261	    if (!existing) {
262	      return Response.json({ error: "Project not found" }, { status: 404 });
263	    }
264	    assertCompanyAccess(ctx, existing.companyId);
265	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
266	    const body = (await ctx.json()) as any;
267	    assertNoAgentHostWorkspaceCommandMutation(
268	      ctx,
269	      collectProjectWorkspaceCommandPaths(body),
270	    );
271	    const workspace = await svc.createWorkspace(id, body);
272	    if (!workspace) {
273	      return Response.json({ error: "Invalid project workspace payload" }, { status: 422 });
274	    }
275	
276	    const actor = getActorInfo(ctx);
277	    await logActivity(db, {
278	      companyId: existing.companyId,
279	      actorType: actor.actorType,
280	      actorId: actor.actorId,
281	      agentId: actor.agentId,
282	      action: "project.workspace_created",
283	      entityType: "project",
284	      entityId: id,
285	      details: {
286	        workspaceId: workspace.id,
287	        name: workspace.name,
288	        cwd: workspace.cwd,
289	        isPrimary: workspace.isPrimary,
290	      },
291	    });
292	
293	    return Response.json(workspace, { status: 201 });
294	  };
295	
296	  const updateProjectWorkspace: Handler = async (ctx) => {
297	    const id = ctx.param("id")!;
298	    const workspaceId = ctx.param("workspaceId")!;
299	    const existing = await svc.getById(id);
300	    if (!existing) {
301	      return Response.json({ error: "Project not found" }, { status: 404 });
302	    }
303	    assertCompanyAccess(ctx, existing.companyId);
304	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
305	    const body = (await ctx.json()) as any;
306	    assertNoAgentHostWorkspaceCommandMutation(
307	      ctx,
308	      collectProjectWorkspaceCommandPaths(body),
309	    );
310	    const workspaceExists = (await svc.listWorkspaces(id)).some((workspace) => workspace.id === workspaceId);
311	    if (!workspaceExists) {
312	      return Response.json({ error: "Project workspace not found" }, { status: 404 });
313	    }
314	    const workspace = await svc.updateWorkspace(id, workspaceId, body);
315	    if (!workspace) {
316	      return Response.json({ error: "Invalid project workspace payload" }, { status: 422 });
317	    }
318	
319	    const actor = getActorInfo(ctx);
320	    await logActivity(db, {
321	      companyId: existing.companyId,
322	      actorType: actor.actorType,
323	      actorId: actor.actorId,
324	      agentId: actor.agentId,
325	      action: "project.workspace_updated",
326	      entityType: "project",
327	      entityId: id,
328	      details: {
329	        workspaceId: workspace.id,
330	        changedKeys: Object.keys(body as Record<string, unknown>).sort(),
331	      },
332	    });
333	
334	    return Response.json(workspace);
335	  };
336	
337	  const handleProjectWorkspaceRuntimeCommand: Handler = async (ctx) => {
338	    const id = ctx.param("id")!;
339	    const workspaceId = ctx.param("workspaceId")!;
340	    const action = String(ctx.param("action") ?? "").trim().toLowerCase();
341	    if (action !== "start" && action !== "stop" && action !== "restart" && action !== "run") {
342	      return Response.json({ error: "Workspace command action not found" }, { status: 404 });
343	    }
344	
345	    const project = await svc.getById(id);
346	    if (!project) {
347	      return Response.json({ error: "Project not found" }, { status: 404 });
348	    }
349	    assertCompanyAccess(ctx, project.companyId);
350	
351	    const workspace = project.workspaces.find((entry) => entry.id === workspaceId) ?? null;
352	    if (!workspace) {
353	      return Response.json({ error: "Project workspace not found" }, { status: 404 });
354	    }
355	
356	    const isSharedWorkspace = Boolean(workspace.sharedWorkspaceKey);
357	    if (
358	      ctx.actor?.type === "agent"
359	      && isSharedWorkspace
360	      && SHARED_WORKSPACE_STOP_AND_RESTART_ACTIONS.has(action)
361	    ) {
362	      throw forbidden("Missing permission to manage workspace runtime services");
363	    }
364	
365	    await assertCanManageProjectWorkspaceRuntimeServices(db, ctx, {
366	      companyId: project.companyId,
367	      projectWorkspaceId: workspace.id,
368	    });
369	
370	    const workspaceCwd = workspace.cwd;
371	    if (!workspaceCwd) {
372	      return Response.json({ error: "Project workspace needs a local path before Paperclip can run workspace commands" }, { status: 422 });
373	    }
374	
375	    const runtimeConfig = workspace.runtimeConfig?.workspaceRuntime ?? null;
376	    const target = (await ctx.json()) as { workspaceCommandId?: string | null; runtimeServiceId?: string | null; serviceIndex?: number | null };
377	    const configuredServices = runtimeConfig ? listConfiguredRuntimeServiceEntries({ workspaceRuntime: runtimeConfig }) : [];
378	    const workspaceCommand = runtimeConfig
379	      ? findWorkspaceCommandDefinition(runtimeConfig, target.workspaceCommandId ?? null)
380	      : null;
381	    if (target.workspaceCommandId && !workspaceCommand) {
382	      return Response.json({ error: "Workspace command not found for this project workspace" }, { status: 404 });
383	    }
384	    if (target.runtimeServiceId && !(workspace.runtimeServices ?? []).some((service) => service.id === target.runtimeServiceId)) {
385	      return Response.json({ error: "Runtime service not found for this project workspace" }, { status: 404 });
386	    }
387	    const matchedRuntimeService =
388	      workspaceCommand?.kind === "service" && !target.runtimeServiceId
389	        ? matchWorkspaceRuntimeServiceToCommand(workspaceCommand, workspace.runtimeServices ?? [])
390	        : null;
391	    const selectedRuntimeServiceId = target.runtimeServiceId ?? matchedRuntimeService?.id ?? null;
392	    const selectedServiceIndex =
393	      workspaceCommand?.kind === "service"
394	        ? workspaceCommand.serviceIndex
395	        : target.serviceIndex ?? null;
396	    if (
397	      selectedServiceIndex !== undefined
398	      && selectedServiceIndex !== null
399	      && (selectedServiceIndex < 0 || selectedServiceIndex >= configuredServices.length)
400	    ) {
401	      return Response.json({ error: "Selected runtime service is not defined in this project workspace runtime config" }, { status: 422 });
402	    }
403	    if (workspaceCommand?.kind === "job" && action !== "run") {
404	      return Response.json({ error: `Workspace job "${workspaceCommand.name}" can only be run` }, { status: 422 });
405	    }
406	    if (workspaceCommand?.kind === "service" && action === "run") {
407	      return Response.json({ error: `Workspace service "${workspaceCommand.name}" should be started or restarted, not run` }, { status: 422 });
408	    }
409	    if (action === "run" && !workspaceCommand) {
410	      return Response.json({ error: "Select a workspace job to run" }, { status: 422 });
411	    }
412	    if ((action === "start" || action === "restart") && !runtimeConfig) {
413	      return Response.json({ error: "Project workspace has no workspace command configuration" }, { status: 422 });
414	    }
415	
416	    const actor = getActorInfo(ctx);
417	    const recorder = workspaceOperations.createRecorder({ companyId: project.companyId });
418	    let runtimeServiceCount = workspace.runtimeServices?.length ?? 0;
419	    let stdout = "";
420	    let stderr = "";
421	
422	    const operation = await recorder.recordOperation({
423	      phase: action === "stop" ? "workspace_teardown" : "workspace_provision",
424	      command: workspaceCommand?.command ?? `workspace command ${action}`,
425	      cwd: workspace.cwd,
426	      metadata: {
427	        action,
428	        projectId: project.id,
429	        projectWorkspaceId: workspace.id,
430	        workspaceCommandId: workspaceCommand?.id ?? target.workspaceCommandId ?? null,
431	        workspaceCommandKind: workspaceCommand?.kind ?? null,
432	        workspaceCommandName: workspaceCommand?.name ?? null,
433	        runtimeServiceId: selectedRuntimeServiceId,
434	        serviceIndex: selectedServiceIndex,
435	      },
436	      run: async () => {
437	        if (action === "run") {
438	          if (!workspaceCommand || workspaceCommand.kind !== "job") {
439	            throw new Error("Workspace job selection is required");
440	          }
441	          return await runWorkspaceJobForControl({
442	            actor: {
443	              id: actor.agentId ?? null,
444	              name: actor.actorType === "user" ? "Board" : "Agent",
445	              companyId: project.companyId,
446	            },
447	            issue: null,
448	            workspace: {
449	              baseCwd: workspaceCwd,
450	              source: "project_primary",
451	              projectId: project.id,
452	              workspaceId: workspace.id,
453	              repoUrl: workspace.repoUrl,
454	              repoRef: workspace.repoRef,
455	              strategy: "project_primary",
456	              cwd: workspaceCwd,
457	              branchName: workspace.defaultRef ?? workspace.repoRef ?? null,
458	              worktreePath: null,
459	              warnings: [],
460	              created: false,
461	            },
462	            command: workspaceCommand.rawConfig,
463	            adapterEnv: {},
464	            recorder,
465	            metadata: {
466	              action,
467	              projectId: project.id,
468	              projectWorkspaceId: workspace.id,
469	              workspaceCommandId: workspaceCommand.id,
470	            },
471	          }).then((nestedOperation) => ({
472	            status: "succeeded" as const,
473	            exitCode: 0,
474	            metadata: {
475	              nestedOperationId: nestedOperation?.id ?? null,
476	              runtimeServiceCount,
477	            },
478	          }));
479	        }
480	
481	        const onLog = async (stream: "stdout" | "stderr", chunk: string) => {
482	          if (stream === "stdout") stdout = appendWithCap(stdout, chunk, WORKSPACE_CONTROL_OUTPUT_MAX_CHARS);
483	          else stderr = appendWithCap(stderr, chunk, WORKSPACE_CONTROL_OUTPUT_MAX_CHARS);
484	        };
485	
486	        if (action === "stop" || action === "restart") {
487	          await stopRuntimeServicesForProjectWorkspace({
488	            db,
489	            projectWorkspaceId: workspace.id,
490	            runtimeServiceId: selectedRuntimeServiceId,
491	          });
492	        }
493	
494	        if (action === "start" || action === "restart") {
495	          const startedServices = await startRuntimeServicesForWorkspaceControl({
496	            db,
497	            actor: {
498	              id: actor.agentId ?? null,
499	              name: actor.actorType === "user" ? "Board" : "Agent",
500	              companyId: project.companyId,
501	            },
502	            issue: null,
503	            workspace: {
504	              baseCwd: workspaceCwd,
505	              source: "project_primary",
506	              projectId: project.id,
507	              workspaceId: workspace.id,
508	              repoUrl: workspace.repoUrl,
509	              repoRef: workspace.repoRef,
510	              strategy: "project_primary",
511	              cwd: workspaceCwd,
512	              branchName: workspace.defaultRef ?? workspace.repoRef ?? null,
513	              worktreePath: null,
514	              warnings: [],
515	              created: false,
516	            },
517	            config: { workspaceRuntime: runtimeConfig },
518	            adapterEnv: {},
519	            onLog,
520	            serviceIndex: selectedServiceIndex,
521	          });
522	          runtimeServiceCount = startedServices.length;
523	        } else {
524	          runtimeServiceCount = selectedRuntimeServiceId ? Math.max(0, (workspace.runtimeServices?.length ?? 1) - 1) : 0;
525	        }
526	
527	        const currentDesiredState: WorkspaceRuntimeDesiredState =
528	          workspace.runtimeConfig?.desiredState
529	          ?? ((workspace.runtimeServices ?? []).some((service) => service.status === "starting" || service.status === "running")
530	            ? "running"
531	            : "stopped");
532	        const nextRuntimeState: {
533	          desiredState: WorkspaceRuntimeDesiredState;
534	          serviceStates: WorkspaceRuntimeServiceStateMap | null | undefined;
535	        } = selectedRuntimeServiceId && (selectedServiceIndex === undefined || selectedServiceIndex === null)
536	          ? {
537	              desiredState: currentDesiredState,
538	              serviceStates: workspace.runtimeConfig?.serviceStates ?? null,
539	            }
540	          : buildWorkspaceRuntimeDesiredStatePatch({
541	              config: { workspaceRuntime: runtimeConfig },
542	              currentDesiredState,
543	              currentServiceStates: workspace.runtimeConfig?.serviceStates ?? null,
544	              action,
545	              serviceIndex: selectedServiceIndex,
546	            });
547	        await svc.updateWorkspace(project.id, workspace.id, {
548	          runtimeConfig: {
549	            desiredState: nextRuntimeState.desiredState,
550	            serviceStates: nextRuntimeState.serviceStates,
551	          },
552	        });
553	
554	        return {
555	          status: "succeeded",
556	          stdout,
557	          stderr,
558	          system:
559	            action === "stop"
560	              ? "Stopped project workspace runtime services.\nThis does not pause issue work or held wake scheduling."
561	              : action === "restart"
562	                ? "Restarted project workspace runtime services.\nThis does not pause issue work or held wake scheduling."
563	                : "Started project workspace runtime services.\n",
564	          metadata: {
565	            runtimeServiceCount,
566	            workspaceCommandId: workspaceCommand?.id ?? target.workspaceCommandId ?? null,
567	            runtimeServiceId: selectedRuntimeServiceId,
568	            serviceIndex: selectedServiceIndex,
569	          },
570	        };
571	      },
572	    });
573	
574	    const updatedWorkspace = (await svc.listWorkspaces(project.id)).find((entry) => entry.id === workspace.id) ?? workspace;
575	
576	    await logActivity(db, {
577	      companyId: project.companyId,
578	      actorType: actor.actorType,
579	      actorId: actor.actorId,
580	      agentId: actor.agentId,
581	      action: `project.workspace_runtime_${action}`,
582	      entityType: "project",
583	      entityId: project.id,
584	      details: {
585	        projectWorkspaceId: workspace.id,
586	        runtimeServiceCount,
587	        workspaceCommandId: workspaceCommand?.id ?? target.workspaceCommandId ?? null,
588	        workspaceCommandKind: workspaceCommand?.kind ?? null,
589	        workspaceCommandName: workspaceCommand?.name ?? null,
590	        runtimeServiceId: selectedRuntimeServiceId,
591	        serviceIndex: selectedServiceIndex,
592	      },
593	    });
594	
595	    return Response.json({
596	      workspace: updatedWorkspace,
597	      operation,
598	    });
599	  };
600	
601	  const deleteProjectWorkspace: Handler = async (ctx) => {
